(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.3)*20 + Math.cos(y*0.013-t*0.22)*14;
  const w1y = Math.cos(y*0.02-t*0.28)*18 + Math.sin(x*0.016+t*0.32)*12;
  const w2x = Math.sin((x+w1x)*0.025-t*0.5)*8 + Math.cos((y+w1y)*0.02+t*0.4)*6;
  const w2y = Math.cos((y+w1y)*0.022+t*0.45)*7 + Math.sin((x+w1x)*0.019-t*0.35)*9;
  const sx = x+w1x+w2x, sy = y+w1y+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.07, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.09, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.055, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.11, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.065, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.08, 1.9],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.3+1)*40, 0.13, 1.4],
    [400+Math.cos(t*0.45+2)*70, 200+Math.sin(t*0.65+4)*50, 0.075, 2.1]
  ];
  let aS=0, iS=0, cross=0;
  for(let i=0;i<src.length;i++){
    const [sX,sY,f,sp]=src[i];
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp);
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    for(let j=i+1;j<src.length;j++){
      const [sX2,sY2]=src[j];
      const mx=(sX+sX2)/2+Math.sin(t*0.8+i+j)*30;
      const my=(sY+sY2)/2+Math.cos(t*0.6+i*j)*25;
      const d2=Math.sqrt((sx-mx)**2+(sy-my)**2);
      cross+=Math.sin(d2*0.04-t*1.8+i*0.5)*0.3;
    }
  }
  const act=aS/8, inh=iS/8, crossN=cross/28;
  const bg=(Math.sin(sx*0.035+sy*0.022+t*0.8)+Math.sin(sx*0.028-sy*0.038+t*1.1))/2
    +Math.sin((sx+sy)*0.11+t*2.5)*0.15+Math.sin((sx-sy)*0.09-t*2)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2), ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.045-ang*3-t*1.5)+Math.sin(dist*0.035+ang*5-t*1.2)
    +Math.sin(dist*0.025-ang*7+t*0.9))*0.3;
  const ripple=Math.sin(dist*0.08-t*3)*Math.exp(-dist*0.008)*0.4;
  const fb1=Math.sin(sx*0.06+t*0.7)*Math.cos(sy*0.05-t*0.5);
  const fb2=Math.sin((sx+sy)*0.04-t*0.9)*Math.sin((sx-sy)*0.05+t*0.6);
  const feedback=(fb1+fb2)*0.2;
  const raw=act-inh*0.6+bg*0.25+spiral+crossN+ripple+feedback;
  const rd=Math.tanh(raw*2.0);
  const cell=Math.tanh((Math.sin(sx*0.12)*Math.sin(sy*0.12)+Math.sin((sx+sy)*0.08+t)*0.5
    +Math.sin(sx*0.06-t*0.4)*Math.cos(sy*0.07+t*0.3)*0.3)*1.8)*0.25;
  const edge=1.0/(1.0+Math.exp(-Math.abs(rd)*8-2))*0.3;
  const blend=rd*0.6+cell*0.2+edge*0.2, v=blend*0.5+0.5;
  const pal=[
    [5,12,52],[10,45,95],[18,95,130],[30,155,145],[120,190,140],
    [210,195,80],[220,145,60],[195,80,75],[140,40,80],[70,20,65],[20,10,45],[5,12,52]
  ];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const pulse=0.85+Math.sin(rd*Math.PI*2)*0.15;
  const glow=Math.max(0,rd)*0.3;
  const lum=pulse+glow;
  const hi=Math.abs(rd)>0.65?1.12:1.0;
  const sh=rd<-0.4?0.85:1.0;
  const m=lum*hi*sh;
  return [
    Math.min(255,Math.max(0,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m))|0,
    Math.min(255,Math.max(0,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m))|0,
    Math.min(255,Math.max(0,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m))|0
  ];
}
